// Get the input item
const item = items[0];
const response = item.json;

// DEBUG: Log the full response to see what we're getting
console.log('=== FULL RESPONSE ===');
console.log(JSON.stringify(response, null, 2));

// Extract text from the response - try multiple approaches
let rawText = '';

// Approach 1: Look for candidates[0].content.parts
try {
  if (response.candidates && response.candidates.length > 0) {
    const candidate = response.candidates[0];

    // Check if candidate has content with parts
    if (candidate.content && candidate.content.parts) {
      const parts = candidate.content.parts;
      console.log('Found parts array with length:', parts.length);

      // Look for the part without "thought: true"
      for (let i = 0; i < parts.length; i++) {
        const part = parts[i];
        console.log(`Part ${i}:`, part);

        if (part.text && !part.thought) {
          rawText = part.text;
          console.log(`✅ Found non-thought text in part ${i}`);
          break;
        }
      }

      // If no non-thought part found, use the last part
      if (!rawText && parts.length > 0) {
        const lastPart = parts[parts.length - 1];
        if (lastPart.text) {
          rawText = lastPart.text;
          console.log('Using last part as fallback');
        }
      }
    }

    // If candidate has text directly
    if (!rawText && candidate.text) {
      rawText = candidate.text;
      console.log('Found text in candidate.text');
    }

    // If candidate has output directly (some models use this)
    if (!rawText && candidate.output) {
      rawText = candidate.output;
      console.log('Found text in candidate.output');
    }
  }
} catch (e) {
  console.error('Error extracting from candidates:', e);
}

// Approach 2: Check if response has content directly
if (!rawText && response.content) {
  try {
    if (response.content.parts) {
      const parts = response.content.parts;
      for (const part of parts) {
        if (part.text && !part.thought) {
          rawText = part.text;
          console.log('Found text in response.content.parts');
          break;
        }
      }
    }
    if (!rawText && response.content.text) {
      rawText = response.content.text;
      console.log('Found text in response.content.text');
    }
  } catch (e) {
    console.error('Error extracting from content:', e);
  }
}

// Approach 3: Check if response has text directly
if (!rawText && response.text) {
  rawText = response.text;
  console.log('Found text in response.text');
}

// Approach 4: Check if response is an array and get the first item
if (!rawText && Array.isArray(response) && response.length > 0) {
  try {
    const firstItem = response[0];
    if (firstItem.text) {
      rawText = firstItem.text;
      console.log('Found text in array[0].text');
    } else if (typeof firstItem === 'string') {
      rawText = firstItem;
      console.log('Found string in array[0]');
    }
  } catch (e) {
    console.error('Error extracting from array:', e);
  }
}

console.log('=== RAW TEXT EXTRACTED ===');
console.log('Length:', rawText.length);
console.log('Preview:', rawText.substring(0, 200));

// Clean up the text
let cleanText = rawText
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .replace(/^json\s*/i, '')
  .trim();

console.log('=== CLEAN TEXT ===');
console.log('Length:', cleanText.length);
console.log('Preview:', cleanText.substring(0, 200));

// Try to find JSON in the text
let receipt = { 
  merchant_name: '', 
  amount: null, 
  subtotal: null,
  date: '', 
  currency: '',
  payment_method: ''
};

if (cleanText) {
  console.log('=== PARSING JSON ===');

  // Try direct parse
  try {
    receipt = JSON.parse(cleanText);
    console.log('✅ Successfully parsed JSON directly');
  } catch (e) {
    console.log('Direct parse failed, looking for JSON in text...');

    // Try to find JSON using regex
    const jsonMatch = cleanText.match(/\{[\s\S]*?\}/);
    if (jsonMatch) {
      try {
        const jsonStr = jsonMatch[0];
        // Validate it's a proper JSON by checking if it has required fields
        if (jsonStr.includes('merchant_name') || jsonStr.includes('amount')) {
          receipt = JSON.parse(jsonStr);
          console.log('✅ Successfully extracted JSON from text');
        } else {
          console.log('Found JSON but missing required fields');
        }
      } catch (e2) {
        console.error('Failed to parse extracted JSON:', e2);
      }
    } else {
      console.log('❌ No JSON found in text');
      // Log the first 500 chars of cleanText for debugging
      console.log('Clean text (first 500 chars):', cleanText.substring(0, 500));
    }
  }
}

// Log what we parsed
console.log('=== PARSED RECEIPT ===');
console.log(JSON.stringify(receipt, null, 2));

// Extract and clean fields
const merchantName = String(receipt.merchant_name || '').trim();
const currency = String(receipt.currency || '').trim();
const receiptDate = String(receipt.date || '').trim();
const paymentMethod = String(receipt.payment_method || '').trim();

// Parse amount
let amount = null;
if (receipt.amount !== null && receipt.amount !== undefined && receipt.amount !== '') {
  const parsed = typeof receipt.amount === 'number' 
    ? receipt.amount 
    : Number(String(receipt.amount).replace(/[^0-9.]/g, ''));
  if (!isNaN(parsed) && parsed > 0 && isFinite(parsed)) {
    amount = parsed;
  }
}

// Parse subtotal
let subtotal = null;
if (receipt.subtotal !== null && receipt.subtotal !== undefined && receipt.subtotal !== '') {
  const parsed = typeof receipt.subtotal === 'number' 
    ? receipt.subtotal 
    : Number(String(receipt.subtotal).replace(/[^0-9.]/g, ''));
  if (!isNaN(parsed) && parsed > 0 && isFinite(parsed)) {
    subtotal = parsed;
  }
}

// Get Telegram data
let telegramUser = '';
let chatId = '';
try {
  const triggerNode = $('Telegram Trigger').first();
  if (triggerNode?.json?.message) {
    const message = triggerNode.json.message;
    telegramUser = message.from?.username || message.from?.first_name || '';
    chatId = message.chat?.id || '';
  }
} catch (e) {
  console.error('Failed to get Telegram data:', e);
}

// Generate date and filename
const submissionDate = $now.toFormat('yyyy-LL-dd');
let fileName = '';
try {
  const fileNode = $('Get Telegram File').first();
  const filePath = fileNode?.json?.file_path || '';
  fileName = filePath.split('/').pop() || `receipt_${submissionDate}_${$now.toFormat('HHmmss')}.jpg`;
} catch (e) {
  fileName = `receipt_${submissionDate}_${$now.toFormat('HHmmss')}.jpg`;
}

// Get binary data
let binaryData = {};
try {
  const fileNode = $('Get Telegram File').first();
  if (fileNode && fileNode.binary) {
    binaryData = fileNode.binary;
  }
} catch (e) {
  console.error('Failed to get binary data:', e);
}

// Return data
return [{
  json: {
    merchantName,
    amount,
    subtotal,
    receiptDate,
    currency,
    paymentMethod,
    submissionDate,
    fileName,
    telegramUser,
    chatId,
    driveRootFolderId: '1oqlPMkotebBtn09ah2hl3gl9-W4zpsYg',
    // Debug info to help identify the issue
    _debug: {
      rawTextLength: rawText.length,
      cleanTextLength: cleanText.length,
      hasMerchantName: !!merchantName,
      receiptKeys: Object.keys(receipt)
    }
  },
  binary: binaryData
}];

// Get items from the Google Drive search
const items = $input.all();

// Initialize variables
let folderExists = false;
let folderId = null;
let folderName = null;

// Check if we have valid results
if (items && items.length > 0) {
    const firstItem = items[0];

    // Check if the item has a valid JSON structure with an ID
    if (firstItem && firstItem.json && firstItem.json.id) {
        folderExists = true;
        folderId = firstItem.json.id;
        folderName = firstItem.json.name || 'Unknown';
    }
}

// IMPORTANT: Always return data, even when folder doesn't exist
return [{
    json: {
        folderExists: folderExists,
        folderId: folderId,
        folderName: folderName,
        // Pass through the original data needed for folder creation
        submissionDate: $('Parse Receipt Data').first().json.submissionDate,
        driveRootFolderId: $('Parse Receipt Data').first().json.driveRootFolderId,
        // Debug info
        debug: {
            itemsReceived: items ? items.length : 0,
            hasValidId: folderExists,
            itemStructure: items && items.length > 0 ? Object.keys(items[0]) : []
        }
    }
}];

const receiptItem = $('Parse Receipt Data').item;
const folderId = $input.item.json.folderId || $input.item.json.id;

return [{
  json: {
    ...receiptItem.json,
    folderId
  },
  binary: receiptItem.binary
}];

